edits.new_string:
    lines = []
    args = []
    for a in attrs:
        # Attribute names that are private by convention are passed without
        # their leading and trailing underscores, e.g. `_x` becomes `x`.  The
        # attribute itself is still set using its full name.
        arg_name = a.name.strip("_")

        if a.validator is not None:
            lines.append("attr_dict['{name}'].validator(attr_dict['{name}'], "
                         "{arg_name})"
                         .format(name=a.name, arg_name=arg_name))
        if a.default_value is not NOTHING:
            args.append(
                "{arg_name}=attr_dict['{name}'].default_value".format(
                    name=a.name,
                    arg_name=arg_name,
                )
            )
            lines.append("self.{name} = {arg_name}".format(
                name=a.name,
                arg_name=arg_name,
            ))
        elif a.default_factory is not NOTHING:
            args.append("{arg_name}=NOTHING".format(arg_name=arg_name))
            lines.extend("""\
if {arg_name} is not NOTHING:
    self.{name} = {arg_name}
else:
    self.{name} = attr_dict["{name}"].default_factory()"""
                         .format(name=a.name, arg_name=arg_name)
                         .split("\n"))
        else:
            args.append(arg_name)
            lines.append("self.{name} = {arg_name}".format(
                name=a.name,
                arg_name=arg_name,
            ))

